  function openMetro(){if(!metro||!active())return false;activity.querySelector('h2').textContent='桃園捷運・A17 ↔ A18 ↔ A19';const body=activity.querySelector('.city-dialog-body');body.replaceChildren();const near=stationIds.map(id=>landmarks.find(l=>l.id===id)).filter(Boolean).sort((a,b)=>Math.hypot(a.entry[0]-walkX,a.entry[1]-walkY)-Math.hypot(b.entry[0]-walkX,b.entry[1]-walkY))[0],available=near&&Math.hypot(near.entry[0]-walkX,near.entry[1]-walkY)<=1400&&mode==='walk'&&!trainRide,p=document.createElement('p');p.textContent=available?'目前在 '+near.name+'。選擇目的站後等候雙向普通車，會停靠沿途車站。':'請先步行前往車站入口；可用下方按鈕導航。';body.append(p);const choices=document.createElement('div');choices.className='npc-choices';for(const station of metro.stations){if(available&&station.id!==near.id){const origin=metro.stations.findIndex(s=>s.id===near.id),destination=metro.stations.findIndex(s=>s.id===station.id),eta=metro.eta(origin,Math.sign(destination-origin));choices.append(button('搭車往 '+station.code+' '+station.name+'・約 '+eta+' 秒候車',()=>rideMRT(near.id,station.id)));}else if(!available)choices.append(button('導航至 '+station.code+' '+station.name,()=>{activity.close();navigate(station.id);}));}const note=document.createElement('small');note.textContent='遊戲接駁班次與車程已縮短，非真實營運時刻表。';body.append(choices,note);show(activity);return true;}
