  function mountNearest(){let best=null;for(const type of ['car','scooter','cycle','borrowed']){const p=parked[type];if(!p||!vehicles[type])continue;const d=Math.hypot(p.x-walkX,p.y-walkY);if(!best||d<best.d)best={type,d};}const candidate=roadTraffic?.nearest([walkX,walkY]);if(candidate&&candidate.d<500&&(!best||candidate.d<best.d)){const taken=roadTraffic.claim(candidate.car);if(taken){if(vehicles.borrowed)world.remove(vehicles.borrowed.group);vehicles.borrowed=taken.vehicle;parked.borrowed={x:taken.p[0],y:taken.p[1],heading:B1_CITY_GEO.heading(taken.u[0],taken.u[1])};return mount('borrowed');}}if(!best||best.d>900){api?.notify('靠近汽車、機車或 YouBike 再上車；小地圖可查看車站。');return false;}return mount(best.type);}
